<script setup lang="ts">
import {onBeforeUnmount,onMounted,watch,ref} from 'vue';
import {createChart,LineStyle,type IChartApi,type ISeriesApi,type IPriceLine,type CandlestickData,type HistogramData,type Time} from 'lightweight-charts';
import type {Candle,Forecast} from '../../types';
const props=defineProps<{candles:Candle[];forecast:Forecast|null;timeframe:string;volumeVisible:boolean}>();
const emit=defineEmits<{ohlc:[candle:Candle|null]}>();
const host=ref<HTMLDivElement>(),boundaryX=ref<number|null>(null);let chart:IChartApi|undefined,price:ISeriesApi<'Candlestick'>|undefined,volume:ISeriesApi<'Histogram'>|undefined,ma20:ISeriesApi<'Line'>|undefined,ma50:ISeriesApi<'Line'>|undefined,predicted:ISeriesApi<'Candlestick'>|undefined,bands:ISeriesApi<'Line'>[]=[],priceLines:IPriceLine[]=[],observer:ResizeObserver|undefined;
const average=(n:number)=>props.candles.flatMap((c,i)=>i<n-1?[]:[{time:c.time as Time,value:props.candles.slice(i-n+1,i+1).reduce((s,x)=>s+x.close,0)/n}]);
function syncBoundary(){const time=props.forecast?.predictedCandles[0]?.time;if(!chart||!time){boundaryX.value=null;return;}const x=chart.timeScale().timeToCoordinate(time as Time);boundaryX.value=x===null?null:Number(x);}
function update(){if(!price||!volume)return;price.setData(props.candles.map(c=>({time:c.time as Time,open:c.open,high:c.high,low:c.low,close:c.close} satisfies CandlestickData)));volume.setData(props.candles.map(c=>({time:c.time as Time,value:c.volume,color:c.close>=c.open?'#00d99766':'#ff526766'} satisfies HistogramData)));volume.applyOptions({visible:props.volumeVisible});ma20?.setData(average(20));ma50?.setData(average(50));if(predicted&&chart){chart.removeSeries(predicted);predicted=undefined;}for(const s of bands)chart?.removeSeries(s);bands=[];for(const l of priceLines)price.removePriceLine(l);priceLines=[];if(props.forecast&&chart){const f=props.forecast;predicted=chart.addCandlestickSeries({upColor:'rgba(0,217,151,.45)',downColor:'rgba(255,82,103,.43)',borderUpColor:'rgba(0,217,151,.72)',borderDownColor:'rgba(255,82,103,.72)',wickUpColor:'rgba(0,217,151,.6)',wickDownColor:'rgba(255,82,103,.6)',priceLineVisible:false});predicted.setData(f.predictedCandles.map(c=>({...c,time:c.time as Time})));if(f.predictedCandles.length)predicted.setMarkers([{time:f.predictedCandles[0]!.time as Time,position:'belowBar',color:f.signal==='SHORT'?'#ff5267':'#00d997',shape:'circle',text:f.entry?`${f.signal} · Entry ${Math.round(f.entry.low).toLocaleString()}–${Math.round(f.entry.high).toLocaleString()}`:f.signal}]);const upper=chart.addLineSeries({color:'rgba(169,88,255,.72)',lineWidth:1,lineStyle:LineStyle.Dashed,priceLineVisible:false,lastValueVisible:false,crosshairMarkerVisible:false});const lower=chart.addLineSeries({color:'rgba(169,88,255,.72)',lineWidth:1,lineStyle:LineStyle.Dashed,priceLineVisible:false,lastValueVisible:false,crosshairMarkerVisible:false});upper.setData(f.uncertainty.map(x=>({time:x.time as Time,value:x.high})));lower.setData(f.uncertainty.map(x=>({time:x.time as Time,value:x.low})));bands=[upper,lower];const addLevel=(value:number|undefined|null,title:string,color:string)=>{if(value&&Number.isFinite(value))priceLines.push(price!.createPriceLine({price:value,color,lineWidth:1,lineStyle:LineStyle.Dashed,axisLabelVisible:true,title}));};addLevel(f.takeProfit,'TP','#00d997');addLevel(f.stopLoss,'SL','#ff5267');if(f.entry){addLevel(f.entry.low,'Entry','#00c48a');addLevel(f.entry.high,'','#00c48a');}}else boundaryX.value=null;chart?.timeScale().fitContent();requestAnimationFrame(syncBoundary);}
onMounted(()=>{if(!host.value)return;chart=createChart(host.value,{layout:{background:{color:'#0b121e'},textColor:'#8795aa',fontFamily:'DM Mono, monospace'},grid:{vertLines:{color:'#172131'},horzLines:{color:'#172131'}},crosshair:{mode:0},rightPriceScale:{borderColor:'#253144'},timeScale:{borderColor:'#253144',timeVisible:true},handleScroll:true,handleScale:true});price=chart.addCandlestickSeries({upColor:'#00d997',downColor:'#ff5267',borderVisible:false,wickUpColor:'#00d997',wickDownColor:'#ff5267'});volume=chart.addHistogramSeries({priceFormat:{type:'volume'},priceScaleId:'volume'});ma20=chart.addLineSeries({color:'#ffbc22',lineWidth:2,priceLineVisible:false,lastValueVisible:false,crosshairMarkerVisible:false});ma50=chart.addLineSeries({color:'#d52bea',lineWidth:2,priceLineVisible:false,lastValueVisible:false,crosshairMarkerVisible:false});chart.priceScale('volume').applyOptions({scaleMargins:{top:.82,bottom:0},visible:false});chart.timeScale().subscribeVisibleLogicalRangeChange(syncBoundary);chart.subscribeCrosshairMove(param=>{const candle=param.seriesData.get(price!) as CandlestickData|undefined;emit('ohlc',candle?{time:Number(candle.time),open:candle.open,high:candle.high,low:candle.low,close:candle.close,volume:0}:null)});observer=new ResizeObserver(entries=>{const w=entries[0]?.contentRect.width;if(w)chart?.applyOptions({width:w})});observer.observe(host.value);update();});
watch(()=>[props.candles,props.forecast,props.volumeVisible],update,{deep:false});
onBeforeUnmount(()=>{observer?.disconnect();chart?.timeScale().unsubscribeVisibleLogicalRangeChange(syncBoundary);chart?.remove();chart=undefined;});
</script>
<template><div class="chart-region"><div class="chart-tools" aria-label="Công cụ biểu đồ"><button title="Crosshair">✣</button><button title="Đường xu hướng">／</button><button title="Mức giá">☷</button><button title="Mẫu">♧</button><button title="Văn bản">T</button><button title="Thêm công cụ">⌄</button><span/><button title="Thước đo">♢</button><button title="Phóng to">⊕</button><button title="Nam châm">∩</button></div><div class="chart-stage"><div ref="host" class="chart-host"/><div v-if="boundaryX!==null" class="forecast-boundary" :style="{left:`${boundaryX}px`}"/></div></div></template>
